import { useDispatch, useSelector } from "react-redux"
import type { AppDispatch, RootState } from "../../redux/store"
import { useNavigate } from "react-router-dom";
import { useEffect, useState } from "react";
import type { UserForgetPassword, UserForgetPasswordError } from "../../types/type";
import { forgetPassword } from "../../redux/authslice";
import { Link } from "react-router-dom";


const ForgetPassword: React.FC = () => {
    const { isLoading, redirectForgetToLogin } = useSelector((state: RootState) => state.auth)
    const dispach = useDispatch<AppDispatch>();
    const navigate = useNavigate();
    const [user, setUser] = useState<UserForgetPassword>({
        email: "",
        answer: "",
        newPassword: ""
    })
    const [error, setError] = useState<UserForgetPasswordError>({});
    const validation = () => {
        let error: UserForgetPasswordError = {};
        if (!user.email) error.email = "please enter your email";
        if (!user.answer) error.answer = "please enter your answer";
        if (!user.newPassword) error.newPassword = "please enter your new Password";
        return error;
    }
    const postUserData = (e: React.ChangeEvent<HTMLInputElement>) => {
        const name = e.target.name;
        const value = e.target.value;
        if (name === "email") {
            if (value.trim().length === 0) {
                setUser({ ...user, email: "" });
                setError({ ...error, email: "please enter your email" })
            }
            else {
                setUser({ ...user, email: value });
                setError({ ...error, email: "" })
            }
        }
        if (name === "answer") {
            if (value.trim().length === 0) {
                setUser({ ...user, answer: "" });
                setError({ ...error, answer: "Please fill your answer in this inputfiled" })
            }
            else {
                setUser({ ...user, answer: value });
                setError({ ...error, answer: "" });
            }
        }
        if (name === "password") {
            if (value.trim().length === 0) {
                setUser({ ...user, newPassword: "" });
                setError({ ...error, newPassword: "Please fill your password in this inputfiled" })
            }
            else {
                setUser({ ...user, newPassword: value });
                setError({ ...error, newPassword: "" });
            }
        }
    }

    const handleSubmit = (e: React.SyntheticEvent) => {
        e.preventDefault();
        let errors = validation();
        setError(errors);
        if (Object.keys(errors).length > 0) return null;
        const data={
            email:user.email,
            answer:user.answer,
            newPassword:user.newPassword
        }
        dispach(forgetPassword(data));
    }

    useEffect(()=>{
        if(redirectForgetToLogin!== null){
            navigate(redirectForgetToLogin);
        }
    },[navigate,redirectForgetToLogin]);


    return(
        <>
       <div className="min-h-screen flex items-center justify-center bg-slate-950 px-6 relative overflow-hidden">
    {/* Background Glow */}
    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[500px] h-[500px] bg-pink-500/10 blur-[120px] pointer-events-none"></div>

    <div className="relative z-10 w-full max-w-md bg-white/5 border border-white/10 backdrop-blur-xl p-10 rounded-3xl shadow-2xl">
        {/* Header Section */}
        <div className="mb-10 text-center">
            <h2 className="text-3xl font-black text-white tracking-tighter uppercase mb-3">
                Recover <span className="text-pink-500">Access</span>
            </h2>
            <p className="text-slate-400 text-[13px] font-medium leading-relaxed">
                Enter your details below to reset your secure password.
            </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
            {/* Email Input */}
            <div className="relative">
                <input 
                    type="email" 
                    name="email" 
                    value={user.email} 
                    onChange={(e)=> postUserData(e)} 
                    className="w-full bg-slate-900/50 border border-white/10 rounded-2xl py-3.5 px-5 text-sm text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-pink-500/50 focus:border-pink-500/50 transition-all duration-300" 
                    placeholder="Email Address" 
                    required
                />
                {error.email && <span className="absolute -bottom-5 left-1 text-[10px] font-bold text-rose-500 uppercase tracking-widest">{error.email}</span>}
            </div>

            {/* Answer Input */}
            <div className="relative pt-2">
                <input 
                    type="text" 
                    name="answer" 
                    value={user.answer} 
                    onChange={(e)=> postUserData(e)} 
                    className="w-full bg-slate-900/50 border border-white/10 rounded-2xl py-3.5 px-5 text-sm text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-pink-500/50 focus:border-pink-500/50 transition-all duration-300" 
                    placeholder="Security Answer" 
                    required
                />
                {error.answer && <span className="absolute -bottom-5 left-1 text-[10px] font-bold text-rose-500 uppercase tracking-widest">{error.answer}</span>}
            </div>

            {/* Password Input */}
            <div className="relative pt-2">
                <input 
                    type="password" 
                    name="password" 
                    value={user.newPassword} 
                    onChange={(e)=> postUserData(e)} 
                    className="w-full bg-slate-900/50 border border-white/10 rounded-2xl py-3.5 px-5 text-sm text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-pink-500/50 focus:border-pink-500/50 transition-all duration-300" 
                    placeholder="New Password" 
                    required
                />
                {error.newPassword && <span className="absolute -bottom-5 left-1 text-[10px] font-bold text-rose-500 uppercase tracking-widest">{error.newPassword}</span>}
            </div>

            {/* Action Button */}
            <button 
                type="submit" 
                className="w-full mt-4 flex items-center justify-center gap-3 bg-gradient-to-r from-pink-600 to-rose-500 text-white py-4 rounded-2xl font-black uppercase text-xs tracking-[0.2em] shadow-lg shadow-pink-500/20 hover:shadow-pink-500/40 hover:-translate-y-0.5 transition-all active:scale-95 disabled:opacity-50 disabled:pointer-events-none" 
                disabled={isLoading}
            >
                {isLoading ? (
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                ) : (
                    "Reset Password"
                )}
            </button>
        </form>

        {/* Footer Links */}
        <div className="mt-10 flex flex-col items-center gap-4 border-t border-white/5 pt-8">
            <Link to="/login" className="text-slate-400 text-xs font-bold uppercase tracking-widest hover:text-white transition-colors">
                Back to <span className="text-pink-500">Login</span>
            </Link>
            <Link to="/register" className="text-slate-500 text-[10px] font-black uppercase tracking-widest hover:text-slate-300 transition-colors">
                Create an account
            </Link>
        </div>
    </div>
</div>

        </>
    )

}
export default ForgetPassword
